package tools; import packet.*;import java.util.List; public final class PacketScan{public static void main(String[] args){try{byte[] data=CliSupport.readBytes(args);PacketInspector inspector=new PacketInspector();List<PacketMetadata> packets=inspector.inspectPcap(data);System.out.print(new PacketSummary().summarize(packets));int i=0;for(PacketMetadata p:packets)System.out.println((i++)+" "+p.flowKey()+" dns="+p.dnsNames()+" notes="+p.notes());}catch(Exception e){CliSupport.exitOnError(e);}}}
